files.lib/sdk/client.ts:
export async function get(url: string) {
  const res = await fetch(url);
  return res.json();
}

files.lib/sdk/uploads.ts:
export async function put(url: string, body: string) {
  const res = await fetch(url, { method: "PUT", body });
  return res.status;
}

